"""Generate a local searchable product comparison from the reviewed reports."""
from pathlib import Path
import csv,json,html,re
ROOT=Path(__file__).parent
text=(ROOT/'FEATURE-DIFFERENCES.md').read_text(encoding='utf-8')
features=[]
for line in text.splitlines():
    if not line.startswith('|'): continue
    cells=[c.strip() for c in line.strip('|').split('|')]
    if len(cells)!=4 or cells[0] in {'Area','---'} or cells[0].startswith('---'):continue
    features.append(dict(zip(['area','vp','rust','difference'],cells)))
with (ROOT/'diagram-coverage.csv').open(encoding='utf-8-sig',newline='') as f: diagrams=list(csv.DictReader(f))
assert len(diagrams)==101 and len({d['constant'] for d in diagrams})==101
assert len(features)>35
(ROOT/'feature-differences.json').write_text(json.dumps(features,indent=2),encoding='utf-8')
def esc(s): return html.escape(s)
def markup(s): return re.sub(r'\*\*([^*]+)\*\*',r'<strong>\1</strong>',esc(s))
fr=''.join('<tr class="feature"><th scope="row">'+esc(x['area'])+'</th><td>'+markup(x['vp'])+'</td><td>'+markup(x['rust'])+'</td><td>'+markup(x['difference'])+'</td></tr>' for x in features)
dr=''.join('<tr class="notation"><th scope="row">'+esc(x['constant'].removeprefix('DIAGRAM_TYPE_').replace('_',' ').title())+'<small>'+esc(x['family'])+'</small></th><td>'+esc(x['our_v01_coverage'])+'<small>'+esc(x['later_milestone'])+'</small></td><td>'+esc(x['key_semantics'])+'</td><td>'+esc(x['ce_evidence_and_uncertainty'])+'</td></tr>' for x in diagrams)
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Visual Paradigm and our Rust plan — differences</title><style>
:root{font:15px/1.6 system-ui;color:#223147;background:#f2f5f9}body{margin:0}*{box-sizing:border-box}main{max-width:1500px;margin:auto;padding:38px 24px}h1{font-size:clamp(27px,4vw,44px);line-height:1.2;max-width:1000px;margin:16px 0}p{max-width:1000px;color:#5a6b82}nav{display:flex;flex-wrap:wrap;gap:18px}a{color:#175eb7}.eyebrow{font-size:12px;letter-spacing:.1em;font-weight:700}.note{border-left:4px solid #d9a54d;padding:12px 18px;background:#fff7e8;color:#5d492e}.facts{display:flex;flex-wrap:wrap;gap:12px;margin:26px 0}.facts div{background:white;padding:15px 24px;border:1px solid #dbe3ee;border-radius:10px}.facts b{display:block;font-size:28px;color:#195ba9}.controls{display:flex;gap:10px;flex-wrap:wrap;margin:24px 0 12px}button,input{font:inherit;padding:10px 14px;border:1px solid #c7d3e1;border-radius:7px;background:white}button{cursor:pointer}button.active{background:#225fbd;color:white;border-color:#225fbd}input{min-width:260px;flex:1;max-width:650px}button:focus-visible,input:focus-visible{outline:3px solid #74a8ee;outline-offset:2px}.tablewrap{overflow:auto;background:white;border:1px solid #dbe3ee;border-radius:10px}table{border-collapse:collapse;width:100%;min-width:900px}th,td{text-align:left;vertical-align:top;border-bottom:1px solid #e2e8f0;padding:15px;font-size:13px}thead{background:#e8eef7}thead th{font-size:12px;text-transform:uppercase;letter-spacing:.04em}tbody th{width:18%}td{width:27%}tbody tr:hover{background:#f7faff}small{display:block;color:#73819a;margin-top:6px}strong{color:#193d70}.hidden{display:none!important}.conclusion{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:16px;margin:24px 0}.conclusion article{padding:20px;background:white;border:1px solid #dbe3ee;border-radius:10px}.conclusion h2{font-size:17px;margin:0 0 6px}.conclusion p{font-size:14px;margin:0}footer{margin-top:24px;color:#63738a;font-size:13px}</style></head><body><main>
<nav><a href="README.md">Comparison report</a><a href="FEATURE-DIFFERENCES.md">Detailed differences</a><a href="BROADER-PRODUCT.md">Broader suite</a><a href="VALIDATION-GAPS.md">Evidence gaps</a><a href="../README.md">Rust plan</a></nav>
<p class="eyebrow">PRODUCT COMPARISON · 4 NOVEMBER 2026</p><h1>What changes when we build our version?</h1><p>Keep the model-based foundation. Simplify common interactions. Deliver a reliable class editor first, with other diagram families and suite capabilities explicitly deferred.</p>
<p class="note">Visual Paradigm is shipped software; our Rust version is an unbuilt plan. These are proposed differences, not measured advantages or a parity score. The 101 constants describe the shared installed API, not 101 enabled Community Edition editors.</p>
<div class="facts"><div><b>0</b>Rust editors implemented</div><div><b>1</b>partial class subset planned first</div><div><b>17</b>installed analytical families</div><div><b>101</b>diagram constants mapped</div></div>
<div class="conclusion"><article><h2>Keep</h2><p>Semantic identity, reusable diagram views, structured members, relations, undo and dependable project files.</p></article><article><h2>Redesign</h2><p>Creation flow, command organization, inspector, model/view wording and visible save feedback.</p></article><article><h2>Defer</h2><p>Most notations, advanced UML, rich export/interchange, reports, engineering, services and collaboration.</p></article><article><h2>Validate</h2><p>Real usability, performance, text shaping, accessibility, recovery and compatibility. Rust alone proves none of these.</p></article></div>
<div class="controls"><button id="features" class="active" aria-pressed="true">Feature differences</button><button id="notations" aria-pressed="false">All diagram types</button><label><span class="hidden">Search comparison</span><input type="search" id="filter" aria-label="Search comparison" placeholder="Search: undo, sequence, export, collaboration…"></label></div><p id="count" aria-live="polite"></p>
<section id="feature-panel"><div class="tablewrap"><table><thead><tr><th>Area</th><th>Visual Paradigm / evidence</th><th>Proposed Rust v0.1</th><th>Difference / decision</th></tr></thead><tbody>'''+fr+'''</tbody></table></div></section>
<section id="notation-panel" class="hidden"><div class="tablewrap"><table><thead><tr><th>Notation / family</th><th>Rust scope / milestone</th><th>Semantics needed</th><th>CE evidence boundary</th></tr></thead><tbody>'''+dr+'''</tbody></table></div></section>
<footer>L = local observation; D = official documentation; P = planned. Detailed reports link to acquisition evidence and official sources. This local page loads no external resources.</footer></main><script>
let mode='feature';const input=document.getElementById('filter');function update(){const rows=Array.from(document.querySelectorAll('.'+mode));let n=0;for(const r of rows){r.hidden=!r.textContent.toLowerCase().includes(input.value.toLowerCase());if(!r.hidden)n++;}document.getElementById('count').textContent=n+' of '+rows.length+' '+(mode==='feature'?'feature comparisons':'diagram constants')+' shown';}function setMode(m){mode=m;document.getElementById('feature-panel').classList.toggle('hidden',m!=='feature');document.getElementById('notation-panel').classList.toggle('hidden',m!=='notation');for(const [id,name] of [['features','feature'],['notations','notation']]){document.getElementById(id).classList.toggle('active',m===name);document.getElementById(id).setAttribute('aria-pressed',String(m===name));}update();}document.getElementById('features').addEventListener('click',()=>setMode('feature'));document.getElementById('notations').addEventListener('click',()=>setMode('notation'));input.addEventListener('input',update);update();
</script></body></html>'''
(ROOT/'COMPARISON.html').write_text(page,encoding='utf-8')
print(json.dumps({'feature_rows':len(features),'diagram_rows':len(diagrams),'families':len({d['family'] for d in diagrams}),'html_bytes':len(page.encode('utf-8'))}))
